1851	 * **different numeric ID** than the original (assigned by the global store's
1852	 * `next_id` counter). The frontend must match by pre-promote ID, not the new ID.
1853	 *
1854	 * @param ledgerRoot  Absolute path to the central ledger root.
1855	 * @param rawId       Raw ID string from the URL parameter (e.g. "42").
1856	 * @param scope       Source scope — must be "project" (global insights cannot be promoted).
1857	 * @param project_slug Required when scope is "project"; the source project slug.
1858	 * @returns The newly created global Insight.
1859	 * @throws ApiError VALIDATION_ERROR if scope is not "project", or insight is already global.
1860	 * @throws ApiError NOT_FOUND if no matching insight exists in the specified scope.
1861	 */
1862	export async function handlePromoteKnowledge(
1863	  ledgerRoot: string,
1864	  rawId: string,
1865	  scope: string | undefined,
1866	  project_slug?: string
1867	): Promise<Insight> {
1868	  const id = parseKnowledgeId(rawId);
1869	
1870	  // Validate scope — must be 'project' (global insights are already global).
1871	  const scopeResult = InsightScope.safeParse(scope);
1872	  if (!scopeResult.success) {
1873	    validationError('scope query parameter is required and must be "global" or "project".');
1874	  }
1875	  const validatedScope = scopeResult.data;
1876	
1877	  if (validatedScope === 'global') {
1878	    validationError('Insight is already global and cannot be promoted.');
1879	  }
1880	
1881	  // project_slug is required when scope === 'project'.
1882	  if (!project_slug) {
1883	    validationError('project_slug query parameter is required when scope is "project".');
1884	  }
1885	
1886	  const manager = new KnowledgeStoreManager(ledgerRoot);
1887	
1888	  // Locate the source insight — throws NOT_FOUND if absent or out-of-scope.
1889	  const source = await findInsightById(manager, id, {
1890	    scope: validatedScope,
1891	    project_slug,
1892	  });
1893	
1894	  // Add-first: create the global copy before deleting the original.
1895	  // eslint-disable-next-line @typescript-eslint/no-unused-vars
1896	  const { id: _sourceId, project_slug: _slug, ...sourceFields } = source;
1897	  const newInsight = await manager.addInsight({
1898	    ...sourceFields,
1899	    scope: 'global',
1900	    project_slug: undefined,
1901	  });
1902	
1903	  // Delete-after: remove the original project-scoped entry.
1904	  try {
1905	    await manager.deleteInsight(id, { scope: validatedScope, project_slug });
1906	  } catch (err) {
1907	    // If deletion fails, the insight exists in both scopes (detectable duplicate).
1908	    // Surface the error so the caller is aware — do not silently swallow it.
1909	    const msg = err instanceof Error ? err.message : String(err);
1910	    if (msg.includes('not found')) {
1911	      throw new ApiError('NOT_FOUND', 'Insight not found during post-promote deletion.');
1912	    }
1913	    throw err;
1914	  }
1915	
1916	  return newInsight;
1917	}
1918	
1919	// ---------------------------------------------------------------------------
1920	// POST /api/knowledge/:id/move
1921	// ---------------------------------------------------------------------------
1922	
1923	/**
1924	 * Zod schema for the POST /api/knowledge/:id/move request body.
1925	 *
1926	 * Required fields:
1927	 * - `source_scope`        — "global" or "project"
1928	 * - `source_project_slug` — required when source_scope is "project"
1929	 * - `project_slug`        — destination project slug (required for all moves)
1930	 */
1931	export const KnowledgeMoveBodySchema = z
1932	  .object({
1933	    source_scope: InsightScope,
1934	    source_project_slug: z.string().regex(PROJECT_SLUG_REGEX).optional(),
1935	    project_slug: z.string().regex(PROJECT_SLUG_REGEX),
1936	  })
1937	  .strict();
1938	
1939	/**
1940	 * Moves an insight from one scope/project to a different project.
1941	 *
1942	 * Supports two move variants:
1943	 * - global → project: promotes the global insight into a named project store
1944	 * - project → project: moves a project insight to a different project
1945	 *
1946	 * Uses add-first-then-delete ordering for the same safety rationale as
1947	 * `handlePromoteKnowledge`.
1948	 *
1949	 * The returned insight is the newly created copy — it has a **different numeric
1950	 * ID** (assigned by the target store's `next_id` counter).
1951	 *
1952	 * @param ledgerRoot  Absolute path to the central ledger root.
1953	 * @param rawId       Raw ID string from the URL parameter (e.g. "42").
1954	 * @param body        Parsed request body (validated against KnowledgeMoveBodySchema).
1955	 * @returns The newly created Insight in the target project store.
1956	 * @throws ApiError VALIDATION_ERROR when source and destination are identical, body is invalid,
1957	 *   or the destination slug fails PROJECT_SLUG_REGEX.
1958	 * @throws ApiError NOT_FOUND when no matching insight exists in the source scope.
1959	 */
1960	export async function handleMoveKnowledge(
1961	  ledgerRoot: string,
1962	  rawId: string,
1963	  body: unknown
1964	): Promise<Insight> {
1965	  const id = parseKnowledgeId(rawId);
1966	
1967	  const parseResult = KnowledgeMoveBodySchema.safeParse(body);
1968	  if (!parseResult.success) {
1969	    validationError('Invalid knowledge move body.', parseResult.error.issues);
1970	  }
1971	
1972	  const { source_scope, source_project_slug, project_slug } = parseResult.data;
1973	
1974	  // Validate that source and destination are not identical.
1975	  const sourceIsGlobal = source_scope === 'global';
1976	  const sameScope = source_scope === 'project';
1977	  const sameSlug = sameScope && source_project_slug === project_slug;
1978	  if (sourceIsGlobal) {
1979	    // global → project always changes the scope — identical destination is impossible.
1980	    // No identity check needed.
1981	  } else if (sameSlug) {
1982	    validationError('Source and destination project are identical; nothing to move.');
1983	  }
1984	
1985	  // Require source_project_slug when source_scope is 'project'.
1986	  if (source_scope === 'project' && !source_project_slug) {
1987	    validationError('source_project_slug is required when source_scope is "project".');
1988	  }
1989	
1990	  const manager = new KnowledgeStoreManager(ledgerRoot);
1991	
1992	  // Locate the source insight.
1993	  const source = await findInsightById(manager, id, {
1994	    scope: source_scope,
1995	    project_slug: source_project_slug,
1996	  });
1997	
1998	  // Add-first: create the target-project copy before deleting the original.
1999	  // eslint-disable-next-line @typescript-eslint/no-unused-vars
2000	  const { id: _sourceId, scope: _scope, project_slug: _oldSlug, ...sourceFields } = source;
2001	  const newInsight = await manager.addInsight({
2002	    ...sourceFields,
2003	    scope: 'project',
2004	    project_slug,
2005	  });
2006	
2007	  // Delete-after: remove the original entry from the source store.
2008	  try {
2009	    await manager.deleteInsight(id, { scope: source_scope, project_slug: source_project_slug });
2010	  } catch (err) {
2011	    const msg = err instanceof Error ? err.message : String(err);
2012	    if (msg.includes('not found')) {
2013	      throw new ApiError('NOT_FOUND', 'Insight not found during post-move deletion.');
2014	    }
2015	    throw err;
2016	  }
2017	
2018	  return newInsight;
2019	}
