2021	// ---------------------------------------------------------------------------
2022	// POST /api/orchestrator/start
2023	// ---------------------------------------------------------------------------
2024	
2025	/**
2026	 * Validates `body.planPath`, then runs preflight checks and (when `dryRun`
2027	 * is `false` and all checks pass) spawns a detached orchestrator process.
2028	 *
2029	 * Throws VALIDATION_ERROR when `body.planPath` is absent or not a string.
2030	 *
2031	 * @param workspaceRoot - Absolute path to the workspace root directory.
2032	 * @param body          - Parsed request body (any shape — validated here).
2033	 */
2034	export async function handleOrchestratorStart(
2035	  workspaceRoot: string,
2036	  body: unknown,
2037	): Promise<StartResult> {
2038	  if (typeof body !== 'object' || body === null) {
2039	    validationError('Request body must be a JSON object.');
2040	  }
2041	  const b = body as Record<string, unknown>;
2042	  if (!('planPath' in b) || typeof b['planPath'] !== 'string') {
2043	    validationError('body.planPath is required and must be a string.');
2044	  }
2045	  const planPath = b['planPath'];
2046	  const dryRun = typeof b['dryRun'] === 'boolean' ? b['dryRun'] : false;
2047	  return startOrchestrator(planPath, workspaceRoot, dryRun);
2048	}
2049	
2050	// ---------------------------------------------------------------------------

