323	function matchRoute(
324	  method: string,
325	  url: string,
326	  ledgerRoot: string,
327	  orchestratorLogsDir: string
328	): RouteHandler | null {
329	  const [path] = url.split('?') as [string];
330	  const segments = path.split('/').filter(Boolean);
331	
332	  // All API routes must start with 'api'
333	  if (segments[0] !== 'api') return null;
334	
335	  const rest = segments.slice(1);
336	
337	  // Route dispatch note:
338	  // Routes are matched by segment count (rest.length) first, then by segment values.
339	  // Because the dispatcher walks the if-else chain in declaration order, two routes
340	  // that share the same rest.length value are ordered by their position here — the
341	  // first matching branch wins and subsequent branches at the same length are shadowed.
342	  // When adding a new route with the same rest.length as an existing one (e.g. a future
343	  // /:slug/synthesis at length 3 alongside /:slug/plan), make sure the more-specific
344	  // pattern appears BEFORE the catch-all pattern at that length, or it will never match.
345	
346	  // GET /api/insights
347	  if (method === 'GET' && rest.length === 1 && rest[0] === 'insights') {
348	    return () => handleGetInsights(ledgerRoot);
349	  }
350	
351	  // GET /api/orchestrator/queue
